package com.bank.qa.perfapi;

// Models the journey (login→accounts→transfer) whose capacity is limited
// by a DB connection pool; past the pool size, latency/errors climb.
class ApiUnderTest {
    private int poolSize;                 // the bottleneck we will tune
    ApiUnderTest(int poolSize) { this.poolSize = poolSize; }
    void setPoolSize(int n) { this.poolSize = n; }

    // Rough model: within pool capacity -> fast; beyond -> queue + errors.
    double p95Ms(int users) {
        int sustainable = poolSize * 50;  // each conn ~50 concurrent-user capacity
        double util = (double) users / sustainable;
        return util <= 1.0 ? 60 + util * 120 : 180 + (util - 1.0) * 1200;
    }
    double errorPct(int users) {
        int sustainable = poolSize * 50;
        return users <= sustainable ? 0.0 : Math.min(50.0, (users - sustainable) * 100.0 / sustainable);
    }
}
