package com.bank.qa.perfapi;

import java.util.logging.*;

public class PerfApiDemo {
    private static final Logger log = Logger.getLogger(PerfApiDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new PaLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    private static int rampAndFindBreak(ApiUnderTest api, int[] userLevels, String label) {
        log.info("=== " + label + " ===");
        int breakAt = -1;
        for (int users : userLevels) {
            double p95 = api.p95Ms(users);
            double err = api.errorPct(users);
            boolean breach = p95 >= 200 || err >= 1.0;    // SLA: p95<200ms, err<1%
            log.info(String.format("users=%4d  p95=%5.0fms  err=%4.1f%%  %s",
                users, p95, err, breach ? "BREACH" : "ok"));
            if (breach && breakAt < 0) breakAt = users;
        }
        log.info("Breaking point ~ " + breakAt + " users");
        return breakAt;
    }

    public static void main(String[] args) {
        // Scenario: login -> accounts -> transfer. Data seeded, prod-like env.
        int[] levels = {100, 500, 1000, 1500, 2000};

        // Initial pool = 10 -> breaks early.
        ApiUnderTest api = new ApiUnderTest(10);
        int before = rampAndFindBreak(api, levels, "Ramp with pool=10 (find breaking point)");

        // DIAGNOSE: server metrics show connection pool saturated -> raise it.
        log.info(">> Diagnosis: DB connection pool saturated at the breaking point.");
        log.info(">> Fix: increase pool 10 -> 30 (and add index on accounts.id).");
        api.setPoolSize(30);

        // RE-TEST: breaking point should move much higher.
        int after = rampAndFindBreak(api, levels, "Re-test with pool=30 (confirm fix)");

        log.info("Improvement: breaking point " + before + " -> " + after + " users (capacity lifted)");
    }
}

